        => _requester.CallAsync<ReportsSnapshotsCreateResponseData?>("POST", "/api/reports/" + Requester.Seg(reportId) + "/snapshots", null, body, false, "data", options, cancellationToken);

    /// <summary>Returns a snapshot with each widget's captured data.</summary>
    /// <remarks>
    /// Needs <c>report.read</c>. Data read as the person who captured it is shown to them alone.
    /// <para/>
    /// <c>GET /api/reports/{reportId}/snapshots/{snapshotId}</c>
    /// </remarks>
    /// <param name="reportId">The report's id.</param>
    /// <param name="snapshotId">The snapshot's id.</param>
