        => _requester.CallAsync<ReportSnapshot?>("GET", "/api/reports/" + Requester.Seg(reportId) + "/snapshots/" + Requester.Seg(snapshotId), null, null, false, "data", options, cancellationToken);

    /// <summary>Lists a report's last 50 snapshots, newest first.</summary>
    /// <remarks>
    /// Needs <c>report.read</c>.
    /// <para/>
    /// <c>GET /api/reports/{reportId}/snapshots</c>
    /// </remarks>
