        => _requester.CallAsync<List<ReportSnapshotSummary>?>("GET", "/api/reports/" + Requester.Seg(reportId) + "/snapshots", null, null, false, "data.items", options, cancellationToken);

    /// <summary>Signs a snapshot, so later changes to its captured data can be detected.</summary>
    /// <remarks>
    /// Needs <c>report.read</c>, edit access and <c>analytics:report_signed_snapshots</c> on the plan. Once per snapshot (409 <c>snapshotAlreadySigned</c>).
    /// <para/>
    /// <c>POST /api/reports/{reportId}/snapshots/{snapshotId}/sign</c>
    /// </remarks>
    /// <param name="reportId">The report's id.</param>
    /// <param name="snapshotId">The snapshot's id.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer's <c>data</c>.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<ReportsSnapshotsSignResponseData?> SignAsync(string reportId, string snapshotId, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<ReportsSnapshotsSignResponseData?>("POST", "/api/reports/" + Requester.Seg(reportId) + "/snapshots/" + Requester.Seg(snapshotId) + "/sign", null, null, false, "data", options, cancellationToken);

    /// <summary>Checks a snapshot's signature against its captured data.</summary>
    /// <remarks>
    /// Needs <c>report.read</c>.
    /// <para/>
    /// <c>GET /api/reports/{reportId}/snapshots/{snapshotId}/sign</c>
    /// </remarks>
    /// <param name="reportId">The report's id.</param>
    /// <param name="snapshotId">The snapshot's id.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
